tool_input.command:
# Create test data files
mkdir -p /tmp/frai-test
cat > /tmp/frai-test/outputs.json << 'EOF'
["hello", "world", "test"]
EOF

cat > /tmp/frai-test/references.json << 'EOF'
["hello", "world", "test"]
EOF

cat > /tmp/frai-test/test_thresholds.js << 'TESTEOF'
import { loadDataset, runEvaluations, generateReport, writeReport } from '/private/tmp/100-tricks-runs/d16/without/h2-eval-thresholds/r3/packages/frai-core/src/eval/index.js';
import fs from 'fs';

const dataset = loadDataset({
  outputsPath: '/tmp/frai-test/outputs.json',
  referencesPath: '/tmp/frai-test/references.json'
});

console.log('Outputs:', dataset.outputs);
console.log('References:', dataset.references);

const evaluations = runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

console.log('Evaluations:', evaluations);

// Test 1: Passing thresholds
const reportPass = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {
    exact_match: 0.5,
    toxicity: 0.8
  }
});

console.log('\n=== Test 1: Passing Thresholds ===');
console.log('Passed:', reportPass.passed);
console.log('Thresholds:', reportPass.thresholds);

// Test 2: Failing threshold
const reportFail = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {
    exact_match: 0.99
  }
});

console.log('\n=== Test 2: Failing Threshold ===');
console.log('Passed:', reportFail.passed);
console.log('Thresholds:', reportFail.thresholds);

// Test 3: No thresholds (backwards compatibility)
const reportNoThreshold = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath
});

console.log('\n=== Test 3: No Thresholds ===');
console.log('Passed field exists:', 'passed' in reportNoThreshold);
console.log('Thresholds field exists:', 'thresholds' in reportNoThreshold);

// Test 4: Write markdown report with thresholds
const mdPath = writeReport({
  report: reportPass,
  format: 'markdown',
  reportPath: '/tmp/frai-test/report.md'
});

console.log('\n=== Test 4: Markdown Report ===');
console.log('Report written to:', mdPath);
console.log('Content:\n');
console.log(fs.readFileSync(mdPath, 'utf8'));
TESTEOF

node /tmp/frai-test/test_thresholds.js
